import requests
import warnings
from json.decoder import JSONDecodeError
from taf.hw.hp.redfish.exceptions import JSONConversionFailed, RequestFailed


class ApiClient(object):
    def __init__(self, configuration, token):
        self.configuration = configuration
        self.token = token
        self.session = requests.Session()
        self.session.verify = False
        self.check_status = True

    def _make_request(self, method, uri, check_status=None, **kwargs):
        url = self.configuration.base_url + uri
        self.session.headers.update({"X-Auth-Token": self.token})
        try:
            with warnings.catch_warnings():
                warnings.simplefilter("ignore")
                self._log_sending_message(url, self.session.headers, method, {**kwargs})
                response = self.session.request(method=method, url=url, **kwargs)

            check_status = self.check_status if check_status is None else check_status
            if check_status:
                response.raise_for_status()

            try:
                response_json = response.json()
                self._log_received_response(response, url, method)
                return response_json
            except JSONDecodeError:
                self.configuration.logger.logger.info(
                     f'response data type is text: {response.status_code}, {response.text}')
                return response.txt
            except Exception as e:
                raise JSONConversionFailed('Json conversion failed: {}'.format(e))
        except requests.exceptions.RequestException as e:
            import traceback
            self.configuration.logger.logger.error(traceback.format_exc())
            raise RequestFailed('Request failed: {}'.format(e))
        except:
            raise

    def send_get_request(self, uri, params=None, check_status=None, **kwargs):
        return self._make_request('get', uri, params=params, check_status=check_status, **kwargs)

    def send_post_request(self, uri, params=None, data=None, json=None, check_status=None, **kwargs):
        return self._make_request('post', uri, params=params, data=data, json=json, check_status=check_status, **kwargs)

    def send_put_request(self, uri, data=None, json=None, check_status=None, **kwargs):
        return self._make_request('put', uri, data=data, json=json, check_status=check_status, **kwargs)

    def send_patch_request(self, uri, data=None, json=None, check_status=None, **kwargs):
        return self._make_request('patch', uri, data=data, json=json, check_status=check_status, **kwargs)

    def send_delete_request(self, uri, check_status=None, **kwargs):
        return self._make_request('delete', uri, check_status, **kwargs)

    def _log_sending_message(self, endpoint, headers, method, payload):
        extra = {
                    "http_request": {
                        "method": method,
                        "url": endpoint,
                        "payload": payload,
                        "headers": headers
                    }
        }

        self.configuration.logger.logger.debug(f"Sending message: {extra}", extra=extra)

    def _log_received_response(self, response, endpoint, method):
        response_content = ' '.join(response.content.decode('utf-8', 'ignore').split())
        if len(response_content) > 1000:
            response_content = response_content[:1000] + '...'

        msg = {
                    "http_response": {
                        "method": method,
                        "url": endpoint,
                        "status_code": response.status_code,
                        "reason": response.reason,
                    }
        }

        extra = msg.copy()
        extra["http_response"]["body"] = response
        msg["http_response"]["body"] = response_content

        self.configuration.logger.logger.debug(f"Received response: {msg}", extra=extra)
